window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f94eb832d9063cd9"]={"versions": [{"id": "FIG-f94eb832d9063cd9", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Feature Model Exchange Format in der AUTOSAR Adaptive und Classic Platform. Das Diagramm modelliert die strukturellen Beziehungen zur Festlegung konkreter Post-Build-Kriteriumswerte innerhalb eines Wertesatzes.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>PostBuildVariantCriterionValueSet: Spezialisiertes ARElement; fungiert als Aggregats-Container und besitzt über eine kompositionelle Beziehung (<code>+postBuildVariantCriterionValue</code>, Kardinalität <code>0..*</code>) mehrere Kriteriumswerte.</li>\n<li>PostBuildVariantCriterionValue: Repräsentiert die Zuweisung eines konkreten ganzzahligen Werts (<code>+ value :Integer</code>, gekennzeichnet mit dem Stereotyp «atpVariation») zu einem Kriterium. Enthält kompositionell Annotationen (<code>+annotation</code>, Kardinalität <code>0..*</code>) vom Typ Annotation (Spezialisierung von GeneralAnnotation).</li>\n<li>PostBuildVariantCriterion: Spezialisiertes ARElement und AtpDefinition; wird von PostBuildVariantCriterionValue über die gerichtete Assoziation <code>+variantCriterion</code> mit der Multiplizität <code>1</code> referenziert.</li>\n<li>Annotation: Spezialisierung von GeneralAnnotation, eingebunden als Dokumentations- bzw. Metadaten-Element.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Metamodellstruktur dar; es werden keine dynamischen Verhaltensweisen, Lebenszyklen oder interaktiven Sequenzabläufe abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>PostBuildVariantCriterionValueSet und PostBuildVariantCriterion sind eigenständige, referenzierbare Modellelemente (<code>ARElement</code>).</li>\n<li>PostBuildVariantCriterion dient als Definitionsinstanz (<code>AtpDefinition</code>), auf die jede Belegung <code>PostBuildVariantCriterionValue</code> genau einfach (<code>1</code>) verweisen muss.</li>\n<li>Das Attribut <code>value</code> unterliegt der AUTOSAR-Variationsbindung («atpVariation»).</li>\n<li>Zur werkzeuggestützten Dokumentation und Nachverfolgbarkeit kann jedes <code>PostBuildVariantCriterionValue</code> mit null bis beliebig vielen Annotationen versehen werden.</li>\n</ul>"}, {"id": "FIG-5e47a133015a7a2f", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Feature Model Exchange Format in der AUTOSAR Adaptive und Classic Platform. Das Diagramm modelliert die strukturellen Beziehungen zur Festlegung konkreter Post-Build-Kriteriumswerte innerhalb eines Wertesatzes.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>PostBuildVariantCriterionValueSet: Spezialisiertes ARElement; fungiert als Aggregats-Container und besitzt über eine kompositionelle Beziehung (<code>+postBuildVariantCriterionValue</code>, Kardinalität <code>0..*</code>) mehrere Kriteriumswerte.</li>\n<li>PostBuildVariantCriterionValue: Repräsentiert die Zuweisung eines konkreten ganzzahligen Werts (<code>+ value :Integer</code>, gekennzeichnet mit dem Stereotyp «atpVariation») zu einem Kriterium. Enthält kompositionell Annotationen (<code>+annotation</code>, Kardinalität <code>0..*</code>) vom Typ Annotation (Spezialisierung von GeneralAnnotation).</li>\n<li>PostBuildVariantCriterion: Spezialisiertes ARElement und AtpDefinition; wird von PostBuildVariantCriterionValue über die gerichtete Assoziation <code>+variantCriterion</code> mit der Multiplizität <code>1</code> referenziert.</li>\n<li>Annotation: Spezialisierung von GeneralAnnotation, eingebunden als Dokumentations- bzw. Metadaten-Element.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Metamodellstruktur dar; es werden keine dynamischen Verhaltensweisen, Lebenszyklen oder interaktiven Sequenzabläufe abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>PostBuildVariantCriterionValueSet und PostBuildVariantCriterion sind eigenständige, referenzierbare Modellelemente (<code>ARElement</code>).</li>\n<li>PostBuildVariantCriterion dient als Definitionsinstanz (<code>AtpDefinition</code>), auf die jede Belegung <code>PostBuildVariantCriterionValue</code> genau einfach (<code>1</code>) verweisen muss.</li>\n<li>Das Attribut <code>value</code> unterliegt der AUTOSAR-Variationsbindung («atpVariation»).</li>\n<li>Zur werkzeuggestützten Dokumentation und Nachverfolgbarkeit kann jedes <code>PostBuildVariantCriterionValue</code> mit null bis beliebig vielen Annotationen versehen werden.</li>\n</ul>"}, {"id": "FIG-680f70d718d8c129", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Feature Model Exchange Format in der AUTOSAR Adaptive und Classic Platform. Das Diagramm modelliert die strukturellen Beziehungen zur Festlegung konkreter Post-Build-Kriteriumswerte innerhalb eines Wertesatzes.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>PostBuildVariantCriterionValueSet: Spezialisiertes ARElement; fungiert als Aggregats-Container und besitzt über eine kompositionelle Beziehung (<code>+postBuildVariantCriterionValue</code>, Kardinalität <code>0..*</code>) mehrere Kriteriumswerte.</li>\n<li>PostBuildVariantCriterionValue: Repräsentiert die Zuweisung eines konkreten ganzzahligen Werts (<code>+ value: Integer</code>, gekennzeichnet mit dem Stereotyp «atpVariation») zu einem Kriterium. Enthält kompositionell Annotationen (<code>+annotation</code>, Kardinalität <code>0..*</code>) vom Typ Annotation (Spezialisierung von GeneralAnnotation).</li>\n<li>PostBuildVariantCriterion: Spezialisiertes ARElement und AtpDefinition; wird von PostBuildVariantCriterionValue über die gerichtete Assoziation <code>+variantCriterion</code> mit der Multiplizität <code>1</code> referenziert.</li>\n<li>Annotation: Spezialisierung von GeneralAnnotation, eingebunden als Dokumentations- bzw. Metadaten-Element.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Metamodellstruktur dar; es werden keine dynamischen Verhaltensweisen, Lebenszyklen oder interaktiven Sequenzabläufe abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>PostBuildVariantCriterionValueSet und PostBuildVariantCriterion sind eigenständige, referenzierbare Modellelemente (<code>ARElement</code>).</li>\n<li>PostBuildVariantCriterion dient als Definitionsinstanz (<code>AtpDefinition</code>), auf die jede Belegung <code>PostBuildVariantCriterionValue</code> genau einfach (<code>1</code>) verweisen muss.</li>\n<li>Das Attribut <code>value</code> unterliegt der AUTOSAR-Variationsbindung («atpVariation»).</li>\n<li>Zur werkzeuggestützten Dokumentation und Nachverfolgbarkeit kann jedes <code>PostBuildVariantCriterionValue</code> mit null bis beliebig vielen Annotationen versehen werden.</li>\n</ul>"}, {"id": "FIG-0594f6e3b55eef60", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Feature Model Exchange Format in der AUTOSAR Adaptive und Classic Platform. Das Diagramm modelliert die strukturellen Beziehungen zur Festlegung von Post-Build-Kriteriumswerten innerhalb eines Wertesatzes sowie Bedingungen für Post-Build-Varianten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>PostBuildVariantCriterionValueSet: Spezialisiertes ARElement; fungiert als Aggregats-Container und besitzt über eine kompositionelle Beziehung (<code>+postBuildVariantCriterionValue</code>, Kardinalität <code>0..*</code>) mehrere Kriteriumswerte.</li>\n<li>PostBuildVariantCriterionValue: Repräsentiert die Zuweisung eines konkreten ganzzahligen Werts (<code>+ value: Integer</code>, gekennzeichnet mit dem Stereotyp «atpVariation») zu einem Kriterium. Enthält kompositionell Annotationen (<code>+annotation</code>, Kardinalität <code>0..*</code>) vom Typ Annotation (Spezialisierung von GeneralAnnotation).</li>\n<li>PostBuildVariantCondition: Bildet eine Bedingung für Varianten ab; besitzt das Attribut <code>+ value: Integer</code> mit Stereotyp «atpVariation» und referenziert über die gerichtete Assoziation <code>+matchingCriterion</code> mit der Multiplizität <code>1</code> das zugehörige PostBuildVariantCriterion.</li>\n<li>PostBuildVariantCriterion: Spezialisiertes ARElement und AtpDefinition; wird sowohl von PostBuildVariantCriterionValue (<code>+variantCriterion</code>, Kardinalität <code>1</code>) als auch von PostBuildVariantCondition (<code>+matchingCriterion</code>, Kardinalität <code>1</code>) referenziert.</li>\n<li>Annotation: Spezialisierung von GeneralAnnotation, eingebunden als Dokumentations- bzw. Metadaten-Element über <code>+annotation</code> (<code>0..*</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Metamodellstruktur dar; es werden keine dynamischen Verhaltensweisen, Lebenszyklen oder interaktiven Sequenzabläufe abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>PostBuildVariantCriterionValueSet und PostBuildVariantCriterion sind eigenständige, referenzierbare Modellelemente (<code>ARElement</code>).</li>\n<li>PostBuildVariantCriterion dient als Definitionsinstanz (<code>AtpDefinition</code>), auf die sowohl Wertebelegungen (<code>PostBuildVariantCriterionValue</code> via <code>+variantCriterion</code>) als auch Bedingungen (<code>PostBuildVariantCondition</code> via <code>+matchingCriterion</code>) mit exakt einfacher Multiplizität (<code>1</code>) verweisen müssen.</li>\n<li>Das Attribut <code>value</code> unterliegt in <code>PostBuildVariantCriterionValue</code> und <code>PostBuildVariantCondition</code> der AUTOSAR-Variationsbindung («atpVariation»).</li>\n<li>Zur werkzeuggestützten Dokumentation und Nachverfolgbarkeit kann jedes <code>PostBuildVariantCriterionValue</code> mit null bis beliebig vielen Annotationen versehen werden.</li>\n</ul>"}], "trans": [{"from": "FIG-f94eb832d9063cd9", "to": "FIG-5e47a133015a7a2f", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5e47a133015a7a2f", "to": "FIG-680f70d718d8c129", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>PostBuildVariantCriterionValue: Attributschreibweise von <code>+ value :Integer</code> in <code>+ value: Integer</code> geändert (Leerzeichen vor dem Doppelpunkt entfernt).</li>\n</ul>"}, {"from": "FIG-680f70d718d8c129", "to": "FIG-0594f6e3b55eef60", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Klasse PostBuildVariantCondition mit dem variablen Attribut <code>+ value: Integer</code> («atpVariation») hinzugefügt.</li>\n<li>Gerichtete Assoziation <code>+matchingCriterion</code> mit Kardinalität 1 von PostBuildVariantCondition auf PostBuildVariantCriterion ergänzt.</li>\n</ul>"}]};
